# Rebuild the exact original Witch's Manor V1 generator and verify uncompressed NBT.
import base64, gzip, hashlib, runpy
from pathlib import Path
here=Path(__file__).resolve().parent
source=gzip.decompress(base64.b64decode("""""",validate=True))
assert hashlib.sha256(source).hexdigest()=="12df5fb3610a0694c843ea21067fc95503230406daf561b5b42e79a34afb2707"
script=here/"build_manor.py"
if script.exists() and script.read_bytes()!=source: raise RuntimeError("Preserve manually edited source before replay")
script.write_bytes(source)
runpy.run_path(str(script),run_name="__main__")
assert hashlib.sha256(gzip.decompress((here/"prefab-extension/witchs_manor.nbt").read_bytes())).hexdigest()=="4343cb8a092aba2e115be4a2b5a4ad38fbc27d02ad954b40252fabf2a485cfac"
